<?php
/** Carga .env local; en Render/Aiven se usan variables de entorno reales. */
$__envFile=__DIR__.'/../.env';if(file_exists($__envFile)){foreach(file($__envFile,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES) as $__envLine){$__envLine=trim($__envLine);if($__envLine===''||str_starts_with($__envLine,'#')||strpos($__envLine,'=')===false)continue;[$k,$v]=explode('=',$__envLine,2);$k=trim($k);$v=trim(trim($v),"\"'");putenv($k.'='.$v);$_ENV[$k]=$v;}}
return ['app_name'=>'MiMarket','base_url'=>getenv('APP_URL')?:'http://localhost:8000','db'=>['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>getenv('DB_PORT')?:'3306','name'=>getenv('DB_NAME')?:'mimarket','user'=>getenv('DB_USER')?:'root','pass'=>getenv('DB_PASS')?:'','ssl_ca'=>getenv('DB_SSL_CA')?:''],'mail'=>['host'=>getenv('SMTP_HOST')?:'','port'=>getenv('SMTP_PORT')?:'587','user'=>getenv('SMTP_USER')?:'','pass'=>getenv('SMTP_PASS')?:'','from'=>getenv('SMTP_FROM')?:getenv('SMTP_USER'),'from_name'=>getenv('SMTP_FROM_NAME')?:'MiMarket','secure'=>getenv('SMTP_SECURE')?:'tls']];
